function designCatalogText() {
  return [
    "B\u1ED8 THI\u1EBET K\u1EBE M\u1EAAU (khi ng\u01B0\u1EDDi d\xF9ng y\xEAu c\u1EA7u l\xE0m theo phong c\xE1ch/thi\u1EBFt k\u1EBF c\u1EE5 th\u1EC3, ch\u1ECDn \u0111\xFAng theme, decorKit, stylePack v\xE0 nh\u1ECBp b\u1ED1 c\u1EE5c t\u01B0\u01A1ng \u1EE9ng):",
    ...SLIDE_DESIGNS.map((d) => {
      const rhythm = d.slides.map((s9) => s9.layout).join(" \u2192 ");
      const skin = skinById(d.id);
      const geo = skin?.geometrySummary ? ` Ng\xF4n ng\u1EEF h\xECnh kh\u1ED1i: ${skin.geometrySummary}` : "";
      return `- ${d.id}: "${d.name}" \u2014 ${d.description} (theme: ${d.themeId}, decorKit: ${d.decorKit ?? "none"}, stylePack: ${d.stylePack ?? "none"}).${geo} Nh\u1ECBp b\u1ED1 c\u1EE5c: ${rhythm}`;
    })
  ].join("\n");
}

// src/lib/aiDeck.ts
function slideCatalogText(includeEditorial = false) {
  const layouts = includeEditorial ? SLIDE_LAYOUTS : SLIDE_LAYOUTS.filter((layout) => !isEditorialLayout(layout.id));
  return [
    'B\u1ED8 M\xC0U (ch\u1ECDn "theme" \u0111\xFAng m\u1ED9t id \u2014 theo ch\u1EE7 \u0111\u1EC1, c\u1EA3m x\xFAc v\xE0 \u0111\u1ED1i t\u01B0\u1EE3ng; tags ch\u1EC9 l\xE0 g\u1EE3i \xFD, kh\xF4ng b\u1EAFt bu\u1ED9c theo m\xF4n):',
    ...DECK_THEMES.map(
      (theme) => `- ${theme.id}: ${theme.name}${theme.vibe ? ` \u2014 ${theme.vibe}` : ""}${theme.tags?.length ? ` (g\u1EE3i \xFD: ${theme.tags.join(", ")})` : ""}${theme.dark ? " \u2014 n\u1EC1n t\u1ED1i" : ""}`
    ),
    "",
    designCatalogText(),
    "",
    stylePackCatalogText(),
    "",
    decorKitCatalogText(),
    "",
    subjectCatalogText(),
    "",
    'B\u1ED0 C\u1EE4C (ch\u1ECDn "layout" \u0111\xFAng m\u1ED9t id; field trong ngo\u1EB7c l\xE0 field n\u1ED9i dung):',
    ...layouts.map(
      (layout) => `- ${layout.id}: ${layout.description} [${layout.fields.join(", ")}]`
    )
  ].join("\n");
}
function slideProCatalogText() {
  return [
    'B\u1ED8 M\xC0U (ch\u1ECDn "theme" \u0111\xFAng m\u1ED9t id theo ch\u1EE7 \u0111\u1EC1):',
    ...PRO_THEMES.map((theme) => `- ${theme.id}: ${theme.name} \u2014 ${theme.vibe}. D\xF9ng cho ${theme.tags?.join(", ")}.`),
    "",
    subjectCatalogText(),
    "",
    'B\u1ED0 C\u1EE4C (ch\u1ECDn "layout" \u0111\xFAng m\u1ED9t id; field trong ngo\u1EB7c l\xE0 field n\u1ED9i dung):',
    ...PRO_LAYOUT_IDS.map((id) => {
      const layout = SLIDE_LAYOUTS.find((l4) => l4.id === id);
      return `- ${layout.id}: ${layout.description} [${layout.fields.join(", ")}]`;
    })
  ].join("\n");
}

