function sourceRule(tier) {
  return `${tierRule(tier)} ${UNTRUSTED_NOTE}`;
}
function liftAskAboveFigure(text) {
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    if (!/^\s*\[Hình[:\]]/.test(lines[i]) || !/\]\s*$/.test(lines[i])) continue;
    let j = i + 1;
    while (j < lines.length && lines[j].trim() && !/^\s*(?:[A-D][.)]|[a-d]\)|(?:Câu|Bài)\s+(?:\d|[IVX])|PHẦN\s|\[Hình|Mệnh đề\b|Đáp án\b)/i.test(lines[j]) && !/\|/.test(lines[j])) j++;
    if (j === i + 1 || j - i > 3) continue;
    const ask = lines.slice(i + 1, j);
    lines.splice(i, j - i, ...ask, lines[i]);
    i = j - 1;
  }
  return lines.join("\n");
}
function sourcePrompt(items) {
  if (!items.length) return "";
  let budget = MAX_SOURCE_CHARS;
  const parts = [];
  items.forEach((item, i) => {
    if (budget <= 0) return;
    const head = `--- NGU\u1ED2N ${i + 1} (\u01B0u ti\xEAn ${item.tier})${item.url ? ` \u2014 ${item.url}` : ""}
${item.name}`;
    const text = liftAskAboveFigure(item.text).slice(0, Math.max(0, budget - head.length - 40));
    budget -= head.length + text.length;
    parts.push(`${head}
${text}`);
  });
  return `NGU\u1ED2N CHO L\u01AF\u1EE2T N\xC0Y:
${parts.join("\n\n")}`;
}
function sourceSection(i) {
  if (!i.withSources) return "";
  const sourceText = sourcePrompt(i.sources ?? []);
  return `

${sourceRule(i.sourceTier ?? 0)}${sourceText ? `

${sourceText}` : ""}${i.khung ? `

${i.khung}` : ""}`;
}
function webSection(found) {
  return found ? `

NGU\u1ED2N T\xCCM TR\xCAN WEB (s\u1ED1 li\u1EC7u m\u1EDBi, \u01B0u ti\xEAn d\xF9ng; s\u1ED1 li\u1EC7u l\u1EA5y t\u1EEB \u0111\xE2y th\xEC ghi ngu\u1ED3n ng\u1EAFn trong \u0111\u1EC1/slide):
${found.trim()}` : "";
}

