var buildSlideBatchSystem = (plan, indices, think, pro) => batchSystemPrompt(plan, indices, pro) + (think ? THINK_VI : "");
var buildSlidePageSystem = (plan, index, pro) => pageSystemPrompt(plan, plan.slides[index], index, pro);
